function toolIconSvg(t){const s=t.slug||'',c=t.category;let k='list';if(c==='ai-bot')k=t.group==='featured'?'brain':t.group==='bot-command'?'terminal':t.engine==='ai'?'sparkles':'wand';else if(s==='qr-to-file')k='scan';else if(s==='qr-url-generator')k='qr';if(c==='foto')k=/crop|potong/.test(s)?'crop':/compress|kompres|resize|ukuran|upscale|brightness|contrast|saturasi/.test(s)?'sliders':/watermark|hapus|restore|unblur|blur|filter|color|meme|kolase|sprite/.test(s)?'wand':'image';else if(c==='teks')k=/json|yaml|xml|csv|code|html|css|js/.test(s)?'braces':/diff|compare|word|karakter|frequency/.test(s)?'list':'text';else if(c==='file')k=/zip|archive/.test(s)?'archive':/search|metadata|extract/.test(s)?'search':/pdf|doc|ppt|xlsx|file/.test(s)?'file':'layers';else if(c==='konverter')k=/time|date|tanggal|clock/.test(s)?'clock':/rate|interest|bmi|loan|kalkulator|calc/.test(s)?'calc':'arrows';else if(c==='keamanan')k=/password|key|otp|totp/.test(s)?'key':/encrypt|decrypt|lock|privacy/.test(s)?'lock':/dns|ip|domain|ssl|whois|rdap|certificate/.test(s)?'globe':'shield';else if(c==='web')k=/url|redirect|link|canonical|href/.test(s)?'link':/dns|ip|domain|http|https|site|website/.test(s)?'globe':/html|css|js|code|generator/.test(s)?'code':'search';else if(c==='qr')k=s.includes('to-file')?'scan':'qr';if(s==='qr-url-generator')k='qr';if(s==='qr-to-file')k='scan';return `<svg viewBox="0 0 24 24" aria-hidden="true">${TOOL_GLYPHS[k]||TOOL_GLYPHS.list}</svg>`}
function card(t){const cls=t.group==='featured'?' tool-card-featured':t.group==='bot-command'?' tool-card-command':'';const mark=t.group==='featured'?'<small class="tool-card-mark">AI UNGGULAN</small>':t.group==='bot-command'?'<small class="tool-card-mark">BOT COMMAND</small>':'';return `<article class="tool-card${cls}" data-tool="${esc(t.slug)}" tabindex="0" role="group" aria-label="Tool ${esc(t.name)}"><button class="tool-info-btn" type="button" data-tool-info="${esc(t.slug)}" aria-label="Informasi ${esc(t.name)}" title="Informasi tool">i</button><span class="tool-symbol">${toolIconSvg(t)}</span><div class="tool-card-copy">${mark}<strong>${esc(t.name)}</strong><p>${esc(t.description)}</p></div></article>`}
function toolInfoMarkup(t){const category=CATS.find(c=>c[0]===t.category)?.[1]||t.category;return `<div class="tool-info-backdrop" data-info-backdrop><section class="tool-info-modal" role="dialog" aria-modal="true" aria-labelledby="toolInfoTitle"><button class="tool-info-close" type="button" data-info-close aria-label="Tutup">×</button><p class="eyebrow">TOOL INFORMATION</p><h3 id="toolInfoTitle">${esc(t.name)}</h3><div class="tool-info-row"><span>Kategori</span><strong>${esc(category)}</strong></div><div class="tool-info-description"><span>DESKRIPSI</span><p>${esc(t.description)}</p></div><div class="tool-info-row"><span>Status</span><strong>${esc(toolState(t))}</strong></div><div class="tool-info-actions"><button class="btn primary" type="button" data-info-open="${esc(t.slug)}">Buka Tool</button><button class="btn" type="button" data-info-close>Tutup</button></div></section></div>`}
function showToolInfo(slug){const t=tools.find(x=>x.slug===slug);if(!t)return;document.getElementById('toolInfoLayer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="toolInfoLayer">${toolInfoMarkup(t)}</div>`);document.body.classList.add('modal-open')}
function closeToolInfo(){document.getElementById('toolInfoLayer')?.remove();document.body.classList.remove('modal-open')}
function ensureHeadingInfoButton(){const title=$('toolTitle');if(!title||title.parentElement.querySelector('.tool-heading-info'))return;const b=document.createElement('button');b.type='button';b.className='tool-heading-info';b.textContent='i';b.setAttribute('aria-label','Informasi tool');b.title='Informasi tool';b.addEventListener('click',e=>{e.stopPropagation();if(activeTool)showToolInfo(activeTool.slug)});title.insertAdjacentElement('afterend',b)}
function routeFromHash(){if(!tools.length)return;const raw=location.hash.replace(/^#/,'');if(!raw||raw==='home'){home();return}const [kind,...rest]=raw.split('=');let value='';try{value=decodeURIComponent(rest.join('='))}catch{return home()}if(kind==='tool'&&tools.some(t=>t.slug===value)){openTool(value);return}if(kind==='category'&&CATS.some(c=>c[0]===value)){openCategory(value);return}home()}
function view(id){['homeView','categories','popular','categoryView','toolView'].forEach(x=>$(x).classList.toggle('hidden',x!==id));window.scrollTo({top:0,behavior:'smooth'})}
