 let ids=['qr-url-generator','kompres-gambar','json-formatter','pdf-merge','password-generator','base64-encode','hapus-latar'];$('popularGrid').innerHTML=ids.map(s=>tools.find(t=>t.slug===s)).filter(Boolean).map(card).join('')
