if(t.group==='featured')return `<div class="ai-chat-shell"><div class="ai-chat-top"><span class="ai-chat-live"></span><strong>DAFZZ CHAT AI</strong><small>AI BAWAAN / SERVER-SIDE</small></div><div id="aiChatHistory" class="ai-chat-history"><div class="ai-chat-empty">Mulai percakapan dengan menulis pertanyaan di bawah. Chat AI menggunakan konfigurasi AI yang diatur administrator.</div></div><div class="control"><label class="control-label" for="input">Pesan kamu</label><textarea id="input" class="field ai-chat-input" rows="3" placeholder="Tanyakan apa saja..."></textarea></div><p class="hint">Jawaban memerlukan koneksi internet dan AI yang aktif pada pengaturan administrator.</p></div>`;
if(t.group==='bot-command')return `<div class="command-preview-panel"><span class="command-preview-label">PERINTAH BOT</span><strong>${esc(t.command||'')}</strong><p class="hint">${esc(t.description)}</p><div class="control"><label class="control-label" for="commandArgs">Parameter perintah (opsional)</label><input id="commandArgs" class="field" placeholder="Isi teks atau parameter perintah..."></div><p class="hint">Salin hasil perintah, lalu kirim dari chat bot yang sudah terhubung. Halaman ini tidak mengirim DM secara langsung.</p></div>`;
if(t.group==='ai-local'&&t.engine==='ai')return `<div class="control"><label class="control-label" for="input">Teks atau topik</label><textarea id="input" class="field" rows="8" placeholder="Tulis kebutuhan atau tempel teks di sini..."></textarea><p class="hint">Fitur ini menggunakan AI aktif dari server DAFZZ. API key tidak dikirim ke browser.</p></div>`;
if(t.group==='ai-local'&&t.engine==='local'){let extra='';if(['text-prefixer','text-suffixer'].includes(slug))extra=`<div class="control"><label class="control-label">${slug==='text-prefixer'?'Awalan':'Akhiran'} untuk setiap baris</label><input id="optA" class="field" placeholder="Contoh: - atau //"></div>`;else if(['text-wrap','text-repeater'].includes(slug))extra=`<div class="control"><label class="control-label">${slug==='text-wrap'?'Lebar baris':'Jumlah pengulangan'}</label><input id="optA" type="number" class="field" value="${slug==='text-wrap'?60:3}" min="1" max="500"></div>`;else if(slug==='unicode-normalizer')extra=`<div class="control"><label class="control-label">Bentuk normalisasi</label><select id="optA" class="field"><option value="NFC">NFC</option><option value="NFKC">NFKC</option><option value="NFD">NFD</option><option value="NFKD">NFKD</option></select></div>`;else if(slug==='template-filler')extra='<p class="hint">Gunakan format: template di bagian atas, satu baris --- sebagai pemisah, lalu pasangan kunci=nilai. Contoh: Halo {{nama}}\n---\nnama=DAFZZ</p>';return `<div class="control"><label class="control-label" for="input">Masukkan teks atau data</label><textarea id="input" class="field" rows="8" placeholder="Masukkan teks atau data di sini..."></textarea></div>${extra}`;}
if(slug==='ocr-gambar')return `<div class="control"><label class="control-label">Pilih gambar</label><input id="fileInput" type="file" accept="image/*"></div><div class="control"><label class="control-label">Teks keterangan</label><textarea id="ocrText" class="field" rows="3" placeholder="Tulis keterangan yang ingin ditambahkan..."></textarea></div><div class="control"><label class="control-label">Posisi keterangan</label><select id="annotationPosition" class="field"><option value="bottom">Bawah gambar</option><option value="top">Atas gambar</option></select></div>`;
if(slug==='deteksi-wajah')return `<div class="control"><label class="control-label">Pilih foto</label><input id="fileInput" type="file" accept="image/*"><p class="hint">Analisis lokal: dimensi, ukuran, rasio aspek, dan kecocokan format untuk profil, banner, atau posting.</p></div>`;
if(['hapus-objek','hapus-orang','hapus-teks-foto','hapus-watermark','hapus-latar'].includes(slug))return `<div class="control"><label class="control-label">Pilih foto</label><input id="fileInput" type="file" accept="image/*"><p class="hint">Editor manual. Gunakan Clone untuk menimpa area dengan tekstur sekitar atau Eraser untuk transparansi. Area lain tetap utuh.</p></div><div class="control-row"><div class="control"><label class="control-label">Mode</label><select id="manualMode" class="field"><option value="clone" ${slug==='hapus-latar'?'':'selected'}>Clone / samarkan</option><option value="erase" ${slug==='hapus-latar'?'selected':''}>Eraser / transparan</option></select></div><div class="control"><label class="control-label">Ukuran kuas</label><input id="maskBrush" type="range" min="6" max="120" value="28" class="field"></div></div><div class="control"><canvas id="maskCanvas" style="display:block;width:100%;max-height:65vh;object-fit:contain;background:#101827;border-radius:12px;touch-action:none"></canvas><p class="hint">Khusus Hapus Teks: sapukan hanya pada tulisan. Foto di luar sapuan tidak dihapus. Clone manual bukan rekonstruksi AI.</p></div>`;
