function toolState(t){
 if(t.group==='featured')return 'AI CHAT · SERVER-SIDE';
 if(t.group==='ai-local'&&t.engine==='ai')return 'AI PROVIDER · INTERNET REQUIRED';
 if(t.group==='ai-local'&&t.engine==='local')return 'LOCAL PROCESSING · NO API';
 if(t.group==='bot-command')return 'TIKTOK DM COMMAND · COPY TO CHAT';
 if(t.slug==='qr-url-generator')return 'QR PNG · URL AUTO-HTTPS';
 if(t.slug==='qr-to-file')return 'QR READER · BROWSER';
 if(t.slug==='konversi-gif')return 'SPRITE SHEET PNG · LOCAL';
 if(t.slug==='ocr-gambar')return 'IMAGE ANNOTATION · LOCAL';
 if(t.slug==='deteksi-wajah')return 'PHOTO DIMENSION ANALYSIS · LOCAL';
 if(['hapus-latar','hapus-objek','hapus-orang','hapus-teks-foto','hapus-watermark'].includes(t.slug))return 'MANUAL PHOTO EDITOR · LOCAL';
 if(['dns-lookup','dns-web-lookup','whois-rdap','ip-lookup','ip-lookup-web'].includes(t.slug))return 'PUBLIC LOOKUP · NETWORK REQUIRED';
 if(['ssl-check','headers-check'].includes(t.slug))return 'HTTPS TEST · CORS MAY LIMIT RESULTS';
 if(['phishing-check','url-safety','domain-reputation','breach-check'].includes(t.slug))return 'LOCAL HEURISTIC · NOT A LIVE REPUTATION CHECK';
 return 'BROWSER TOOL · CHECK THE RESULT';
}
function openTool(slug){activeTool=tools.find(x=>x.slug===slug);if(!activeTool)return;activeCategory=activeTool.category;if(slug==='chat-ai')chatAiHistory=[];$('toolCategory').textContent='DAFZZ TOOLS / '+(CATS.find(c=>c[0]===activeTool.category)?.[1]||activeTool.category).toUpperCase();$('toolTitle').textContent=activeTool.name;ensureHeadingInfoButton();$('toolDescription').textContent=activeTool.description;$('toolInputArea').innerHTML=inputMarkup(activeTool);$('toolStatus').textContent=toolState(activeTool);$('status').textContent='';$('output').value='';hide('resultArea');hide('previewArea');lastBlob=null;$('serverDownloadLink')?.classList.add('hidden');if(dafzzRunToken)$('downloadBtn')?.classList.add('hidden');else $('downloadBtn')?.classList.remove('hidden');$('processBtn').textContent=activeTool.group==='featured'?'Kirim pertanyaan':activeTool.group==='ai-local'&&activeTool.engine==='ai'?'Kirim ke AI':activeTool.group==='bot-command'?'Buat perintah':'Jalankan alat';$('relatedTools').innerHTML=tools.filter(x=>x.category===activeTool.category&&x.slug!==slug&&x.group!=='bot-command').slice(0,4).map(card).join('');view('toolView')}
const val=id=>$(id)?.value??'';const num=id=>Number(val(id)||0);
const dafzzRunToken=location.pathname.match(/^\/run\/([A-Za-z0-9_-]+)$/)?.[1]||'';
async function dafzzSendResultToServer(text,name,blob){
 if(!dafzzRunToken)return;
 const payload=blob instanceof Blob?blob:new Blob([String(text??'')],{type:'text/plain;charset=utf-8'});
 const form=new FormData();form.append('file',payload,name||'hasil.txt');
 try{
  const response=await fetch(`/api/run/${encodeURIComponent(dafzzRunToken)}/result`,{method:'POST',body:form});
  const data=await response.json().catch(()=>({}));
  if(!response.ok)throw Error(data.error||`Server ${response.status}`);
  const link=$('serverDownloadLink');link.href=data.downloadUrl;link.download=data.fileName;link.classList.remove('hidden');
  const platformLabel = ({tiktok:'TikTok DM',telegram:'Telegram',whatsapp:'WhatsApp'})[data.platform] || 'chat bot';
  $('status').textContent=(data.notified || data.notifiedTikTok)?`Selesai. Tautan hasil telah dikirim kembali ke ${platformLabel}.`:'Selesai. Hasil tersimpan di server; balasan ke chat belum berhasil. Gunakan tautan unduhan di halaman ini.';
 }catch(error){$('status').textContent='Hasil selesai di browser, tetapi belum terkirim ke bot: '+error.message;}
}
function result(s,name='hasil.txt',blob=null){$('output').value=String(s??'');lastName=name;lastBlob=blob;show('resultArea');$('status').textContent='Selesai. Periksa hasil sebelum mengunduh.';$('serverDownloadLink')?.classList.add('hidden');if(dafzzRunToken)void dafzzSendResultToServer(s,name,blob)}
function downloadBlob(blob,name){if(dafzzRunToken){if(blob===lastBlob&&name===(lastName||'hasil.txt')){$('status').textContent='Hasil sudah dikirim ke server DAFZZ untuk dibagikan melalui DM.';return}void dafzzSendResultToServer('',name,blob);return}const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
