function domainFromInput(raw){let v=String(raw||'').trim();if(!v)throw Error('Masukkan nama domain.');try{if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(v))v='https://'+v;return new URL(v).hostname.toLowerCase()}catch{throw Error('Nama domain atau URL tidak valid.')}}
