async function loadQrLibrary(globalName){
 if(window[globalName])return window[globalName];
 if(globalName==='QRCode'){
  // QR generation is bundled locally: no CDN/API/network required.
  await new Promise((resolve,reject)=>{const x=document.createElement('script');x.src='./qrcode-local.js';x.onload=resolve;x.onerror=()=>reject(Error('File qrcode-local.js tidak ditemukan. Pastikan ikut diunggah bersama ZIP.'));document.head.append(x)});
  if(window.QRCode&&typeof window.QRCode.toCanvas==='function')return window.QRCode;
  throw Error('Encoder QR lokal gagal diinisialisasi.');
 }
 // Native BarcodeDetector is preferred by decodeQrFromFile; jsQR is a fallback
 // for browsers that do not implement the Barcode Detection API.
 for(const url of ['https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js','https://unpkg.com/jsqr@1.4.0/dist/jsQR.js']){
  try{const lib=await loadLib(url,'jsQR');if(typeof lib==='function')return lib;}catch(e){}
 }
 throw Error('Browser ini tidak mendukung pemindai QR bawaan dan jsQR tidak dapat dimuat. Gunakan Chrome terbaru atau sambungkan internet.');
}
async function decodeQrFromFile(file){
 if(!file)throw Error('Pilih foto yang berisi QR Code.');
 if(!file.type || !file.type.startsWith('image/'))throw Error('File harus berupa gambar.');
 if(typeof createImageBitmap!=='function')throw Error('Browser ini belum mendukung pembacaan gambar.');
 const bmp=await createImageBitmap(file);
 try{
  const maxSide=2400,scale=Math.min(1,maxSide/Math.max(bmp.width,bmp.height));
  const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});
  canvas.width=Math.max(1,Math.round(bmp.width*scale));canvas.height=Math.max(1,Math.round(bmp.height*scale));
  if(!ctx)throw Error('Browser tidak dapat membuat canvas untuk membaca QR.');
  ctx.drawImage(bmp,0,0,canvas.width,canvas.height);
  let code=null;
  if('BarcodeDetector' in window){try{const detector=new BarcodeDetector({formats:['qr_code']});const found=await detector.detect(canvas);if(found.length)code={data:found[0].rawValue};}catch(e){}}
  if(!code){const jsQR=await loadQrLibrary('jsQR');const image=ctx.getImageData(0,0,canvas.width,canvas.height);code=jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'});}
  if(!code)throw Error('QR Code tidak ditemukan. Coba foto yang lebih jelas, tidak miring, dan QR tidak terpotong.');
  $('previewArea').innerHTML=`<img alt="Foto QR yang dibaca" src="${URL.createObjectURL(file)}"><p class="hint">QR berhasil dibaca.</p>`;
  show('previewArea');
  result(code.data,'qr-hasil.txt',new Blob([code.data],{type:'text/plain;charset=utf-8'}));
 }finally{bmp.close?.();}
}
function normalizeQrPayload(raw){
 const value=String(raw??'').trim();
 if(!value)throw Error('Masukkan teks atau URL yang ingin dijadikan QR Code.');
 if(/^[a-z][a-z0-9+.-]*:\/\//i.test(value)||/^(mailto|tel|sms|geo):/i.test(value))return value;
 // Add a protocol only to values that look like a domain, not to ordinary text.
 const domainLike=/^(?:www\.)?(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}(?::\d{1,5})?(?:[/?#][^\s]*)?$/i;
 if(domainLike.test(value))return 'https://'+value;
 return value;
}
async function makeQr(s){
 const value=normalizeQrPayload(s);
 const lib=await loadQrLibrary('QRCode');
 const canvas=document.createElement('canvas');
 await lib.toCanvas(canvas,value,{width:360,margin:3,errorCorrectionLevel:'M',color:{dark:'#07111f',light:'#FFFFFF'}});
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Gagal membuat file PNG QR.')),'image/png'));
 $('previewArea').innerHTML='';
 const frame=document.createElement('div');frame.className='qr-result-frame';frame.appendChild(canvas);
 const note=document.createElement('p');note.className='hint qr-payload';note.textContent='Isi QR: '+value;frame.appendChild(note);
 $('previewArea').appendChild(frame);show('previewArea');
 result('QR Code berhasil dibuat.\nIsi QR persis seperti berikut:\n'+value,'qr-code.png',blob);
}
