 const suggestions=ratio>=.95&&ratio<=1.05?'Cocok untuk gambar profil persegi.':ratio>=.5&&ratio<=.8?'Cocok untuk konten portrait.':ratio>=1.6&&ratio<=2?'Cocok untuk gambar landscape.':'Sesuaikan crop dengan platform tujuan.';
