 images.forEach((img,i)=>{const x=gap+(i%cols)*(cell+gap),y=gap+Math.floor(i/cols)*(cell+gap);ctx.fillStyle='#132b45';ctx.fillRect(x,y,cell,cell);const scale=Math.min((cell-18)/img.width,(cell-18)/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,x+(cell-w)/2,y+(cell-h)/2,w,h);});
