 const u=URL.createObjectURL(blob);$('previewArea').innerHTML=`<img alt="Hasil edit manual" src="${u}"><p class="hint">Area yang tidak disapukan tetap dipertahankan.</p>`;show('previewArea');result('Edit manual selesai.','hasil-edit-manual.png',blob);
